const diagramUrls={};
window.renderRichVisual=q=>{
 const svg=DIAGRAMS[q.n];
 if(!svg)return '<p class="asset-warning" role="alert">この問題の解説図が見つかりません。最新版のapp.jsに更新してください。</p>';
 const url=diagramUrls[q.n]||(diagramUrls[q.n]=URL.createObjectURL(new Blob([svg],{type:"image/svg+xml"})));
 return `<a class="diagram-link" href="${url}" target="_blank" rel="noopener" aria-label="問${q.n}の解説図を拡大">${svg}<span>図を拡大 ↗</span></a>`;
};
